import gzip,glob,csv
for n in [3,4,5]:
 f=glob.glob(f'studies/data/raw/paper_{n}_*matrix*')[0]; rows=list(csv.reader(gzip.open(f,'rt'),delimiter='\t'))
 print('\nPAPER',n)
 for r in rows:
