from pypdf import PdfReader
import re
for n in [1,2,3,5]:
 t='\n'.join(p.extract_text() for p in PdfReader(f'studies/papers/paper_{n}.pdf').pages)
 print('\nPAPER',n)
 pats=['microarray','24 h','24h','hydroxytam','RNA sequencing','RNA-seq','normaliz']
 spans=[]
 for p in pats:
  for m in re.finditer(p,t,re.I):
   a,b=max(0,m.start()-350),min(len(t),m.end()+650)
   if not any(a<y and b>x for x,y in spans):spans.append((a,b)); print(t[a:b].replace('\n',' '))

